with flagged as (select *, case when lag(reading_ts) over (partition by device_code order by reading_ts, id) is null or reading_ts > lag(reading_ts) over (partition by device_code order by reading_ts, id) + interval 1 hour then 1 else 0 end as is_new_session from device_readings), islands as (select *, sum(is_new_session) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as island_id from flagged) select id, reading_ts, temp_c, humidity, pressure, firmware, is_new_session from islands order by firmware desc;
